{
  short delta;
  short reserved;
  void *function;
};

class entity
{
  char prefix[8];
  virtual_entry *vtable;

public:
  collision_geometry *get_colgeom() const
  {
    typedef collision_geometry *(*function_type)(const void *);
    virtual_entry &entry = vtable[55];
    return ((function_type)entry.function)((const char *)this + entry.delta);
  }

  bool are_collisions_active() const
  {
    typedef bool (*function_type)(const void *);
    virtual_entry &entry = vtable[33];
    return ((function_type)entry.function)((const char *)this + entry.delta);
  }
};

extern entity **find_entity_pointer(entity **, entity **, entity *const &, int)
