class entity_vector
{
public:
  entity **begin_pointer;
  entity **end_pointer;
  entity **capacity_pointer;

  entity **begin() { return begin_pointer; }
  entity **end() { return end_pointer; }
  void push_back(entity *const &value);
};

extern void insert_entity_pointer(entity_vector *, entity **, entity *const &)
  __asm__("_M_insert_aux__t6vector2ZP6entityZt12my_allocator1ZP6entityPP6entityRCP6entity");

void entity_vector::push_back(entity *const &value)
{
