  {
    if (end_pointer)
      *end_pointer = value;
    ++end_pointer;
  }
  else
    insert_entity_pointer(this, end_pointer, value);
}

class region
{
  char prefix[0xac];
  entity_vector possible_collide_ents;

public:
  void update_poss_collide(entity *e);
};

void region::update_poss_collide(entity *e)
{
  if(e)
  {
    if(e->get_colgeom() && e->are_collisions_active())
    {
      entity **ei_begin = possible_collide_ents.begin();
      entity **ei_end = possible_collide_ents.end();

      entity **ei = find_entity_pointer(ei_begin, ei_end, e, 0);
      if (ei == ei_end)
      {
        entity *null_entity = 0;
        ei = find_entity_pointer(ei_begin, ei_end, null_entity, 0);
        if (ei != ei_end)
          *ei = e;
        else
          possible_collide_ents.push_back(e);
      }
    }
    else
    {
      entity **ei_end = possible_collide_ents.end();
      entity **ei = find_entity_pointer(possible_collide_ents.begin(), ei_end, e, 0);
      if (ei != ei_end)
        *ei = 0;
    }
  }
}
